using UnityEngine;
public enum StreetLegendMissionStage{HotelCombat,DrivingPursuit,Roadblock,PostRoadblockCombat,Complete}
/// <summary>Campaign phase coordinator, with independent roadblock fight and victory handoff.</summary>
public class StreetLegendMissionPhase:MonoBehaviour{
 public StreetLegendVehicleController vehicle;public GameObject drivingHUD,combatHUD,roadblockHUD;public PrototypeMobileHUD mobileHUD;
 public PrototypeFighterController player,roadblockFighter;public PrototypeOpponent roadblockOpponent;
 public Transform safeExitPoint,roadblockOpponentPoint;public StreetLegendMissionStage phase=StreetLegendMissionStage.HotelCombat;
 bool triggered,combatStarted,won;void Update(){if(phase==StreetLegendMissionStage.PostRoadblockCombat&&!won&&roadblockOpponent&&roadblockOpponent.Health<=0){won=true;Finish();}}
 public void BeginPursuit(){if(phase!=StreetLegendMissionStage.HotelCombat)return;phase=StreetLegendMissionStage.DrivingPursuit;if(vehicle){vehicle.gameObject.SetActive(true);vehicle.SetDrivingEnabled(true);}if(drivingHUD)drivingHUD.SetActive(true);if(combatHUD)combatHUD.SetActive(false);if(mobileHUD)mobileHUD.SetHUDVisible(false);}
 public void RoadblockReached(){if(phase!=StreetLegendMissionStage.DrivingPursuit||triggered)return;triggered=true;phase=StreetLegendMissionStage.Roadblock;if(vehicle){vehicle.StopVehicle();vehicle.SetDrivingEnabled(false);}if(drivingHUD)drivingHUD.SetActive(false);if(player){if(safeExitPoint)player.transform.position=safeExitPoint.position;player.ResetVerticalMotion();player.enabled=true;}if(roadblockFighter){roadblockFighter.gameObject.SetActive(true);if(roadblockOpponentPoint)roadblockFighter.transform.position=roadblockOpponentPoint.position;roadblockFighter.enabled=true;}if(roadblockOpponent){roadblockOpponent.gameObject.SetActive(true);if(player)roadblockOpponent.SetTarget(player.transform);}if(player&&roadblockFighter)player.SetOpponent(roadblockFighter.transform);if(mobileHUD)mobileHUD.RefreshOpponent();BeginRoadblockCombat();}
 public void BeginRoadblockCombat(){if(phase!=StreetLegendMissionStage.Roadblock||combatStarted)return;combatStarted=true;phase=StreetLegendMissionStage.PostRoadblockCombat;if(combatHUD)combatHUD.SetActive(true);if(mobileHUD)mobileHUD.SetHUDVisible(true);if(mobileHUD)mobileHUD.SetHUDVisible(true);if(roadblockHUD)roadblockHUD.SetActive(true);}
 public void Finish(){if(phase!=StreetLegendMissionStage.PostRoadblockCombat)return;phase=StreetLegendMissionStage.Complete;if(roadblockHUD)roadblockHUD.SetActive(false);if(combatHUD)combatHUD.SetActive(false);if(mobileHUD)mobileHUD.SetHUDVisible(false);if(player)player.enabled=false;if(roadblockOpponent)roadblockOpponent.enabled=false;Debug.Log("Level 1 roadblock encounter cleared. Campaign handoff is ready.");}
 public void ResetMission(){triggered=combatStarted=won=false;phase=StreetLegendMissionStage.HotelCombat;if(vehicle){vehicle.StopVehicle();vehicle.SetDrivingEnabled(false);}if(drivingHUD)drivingHUD.SetActive(false);if(roadblockHUD)roadblockHUD.SetActive(false);if(combatHUD)combatHUD.SetActive(true);}
}